insert into public.events (id, slug, title, description, product_ids, is_active) values
  ('e1000000-0000-4000-8000-000000000001', 'jangdok-week', '장독 위크', '된장, 고추장, 간장을 한 번에 채우는 일주일입니다. 장류 쿠폰 JANG5000을 함께 받아 보세요.', array['p1000000-0000-4000-8000-000000000004','p1000000-0000-4000-8000-000000000005','p1000000-0000-4000-8000-000000000006','p1000000-0000-4000-8000-000000000016']::uuid[], true),
  ('e1000000-0000-4000-8000-000000000002', 'one-plus-one', '1+1 양념 위크', '만능 양념장과 매콤 비빔양념을 모았습니다. 1+1 뱃지는 기획 표시이며, 결제 금액은 판매가 그대로입니다.', array['p1000000-0000-4000-8000-000000000001','p1000000-0000-4000-8000-000000000003']::uuid[], true)
