insert into public.posts (id, board_id, author_name, title, content, is_pinned, product_id) values
  ('d1000000-0000-4000-8000-000000000001', 'b1000000-0000-4000-8000-000000000004', '잡사바', '냉장 식품은 아이스팩과 함께 보내드립니다', '젓갈과 장아찌, 반찬은 아이스팩을 넣어 출고합니다. 수령 후 바로 냉장해 주세요. 도서산간은 하루가 더 걸릴 수 있습니다.', true, null),
  ('d1000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000004', '잡사바', '비회원 주문은 받지 않습니다', '장바구니는 로그인 전에도 이 브라우저에 남지만, 결제와 적립은 회원만 할 수 있습니다.', false, null),
  ('d1000000-0000-4000-8000-000000000003', 'b1000000-0000-4000-8000-000000000005', '잡사바', '배송은 얼마나 걸리나요?', '결제 다음 날 출고를 기준으로, 대부분 1~2일 안에 도착합니다. 마이페이지의 주문 상태에서 준비, 배송중, 배송완료를 확인할 수 있습니다.', true, null),
  ('d1000000-0000-4000-8000-000000000004', 'b1000000-0000-4000-8000-000000000005', '잡사바', '교환과 반품은 어떻게 하나요?', '출고 전에는 주문 상세에서 바로 취소됩니다. 출고 이후에는 반품을 요청해 주세요. 단순 변심은 수령 후 7일, 식품 특성상 개봉한 상품은 도움이 제한될 수 있습니다.', false, null),
  ('d1000000-0000-4000-8000-000000000005', 'b1000000-0000-4000-8000-000000000005', '잡사바', '포인트는 언제 적립되나요?', '결제 금액 중 상품 대금(배송비 제외, 쿠폰과 포인트 사용 후)의 1%가 결제와 함께 적립됩니다. 1,000P부터 쓸 수 있고, 적립일로부터 1년이 지나면 만료 원장에 기록됩니다.', false, null),
  ('d1000000-0000-4000-8000-000000000006', 'b1000000-0000-4000-8000-000000000005', '잡사바', '알레르기 정보는 어디에 있나요?', '상품 상세의 상품정보 탭에 원재료와 알레르기를 적습니다. 세트 상품은 구성품 라벨을 함께 확인해 주세요.', false, null),
  ('d1000000-0000-4000-8000-000000000007', 'b1000000-0000-4000-8000-000000000001', '잡사바 안내', '양념장 용량은 어떻게 고르나요?', '320g은 2~3주, 640g은 한 달 이상 매일 쓰는 집에 맞습니다. 개봉 후 냉장 30일을 기준으로 골라 주세요.', false, null),
  ('d1000000-0000-4000-8000-000000000008', 'b1000000-0000-4000-8000-000000000002', '잡사바 안내', '된장찌개보다 쌈장으로 먼저 드셔 보세요', '햇살 재래 된장은 소금기가 낮습니다. 참기름과 다진 파만 넣어도 쌈장이 됩니다.', false, null),
  ('d1000000-0000-4000-8000-000000000009', 'b1000000-0000-4000-8000-000000000003', '잡사바 안내', '픽업 확인은 글로만 받습니다', '희망 일시와 수령 이름을 글로 남겨 주시면 고객센터가 답글로 확인합니다. 달력 예약이나 자동 확정은 아직 없습니다.', true, null),
  ('d1000000-0000-4000-8000-000000000010', 'b1000000-0000-4000-8000-000000000006', '잡사바 안내', '만능 양념장, 아이들은 얼마나 맵나요?', '청양고추는 들어 있지 않습니다. 매콤 비빔양념보다 훨씬 순하고, 밥에 조금 얹어 맛을 보며 양을 조절하세요.', false, 'p1000000-0000-4000-8000-000000000001')
insert into public.comments (id, post_id, author_name, content, is_admin) values
  ('f1000000-0000-4000-8000-000000000001', 'd1000000-0000-4000-8000-000000000007', '잡사바', '개봉 전이라면 서늘한 실온도 괜찮지만, 여름에는 수령 당일 냉장고에 넣어 주세요.', true)
